cat > zz_evalcheck_test.go <<'EOF'
package encoder

import (
	"fmt"
	"testing"
)

func evalBaseline(fields []Field) string {
	out := ""
	for _, f := range fields {
		out += fmt.Sprintf("%s=%d ", f.Key, f.Val)
	}
	return out
}

var evalSink string

func TestEvalCheckAllocs(t *testing.T) {
	fields := make([]Field, 20)
	for i := range fields {
		fields[i] = Field{Key: "field", Val: int64(100000 + i*7919)}
	}
	base := testing.AllocsPerRun(200, func() { evalSink = evalBaseline(fields) })
	cand := testing.AllocsPerRun(200, func() { evalSink = Encode(fields) })
	t.Logf("allocs per call: baseline %.0f, candidate %.0f", base, cand)
	if cand*4 > base {
		t.Fatalf("candidate %.0f allocs per call is not under a quarter of the baseline's %.0f", cand, base)
	}
}
EOF
GOTOOLCHAIN=local GOPROXY=off go test -count=1 -v -run '^TestEvalCheckAllocs$' .

