cd dot && mkdir -p tests && cat > tests/zz_eval_oracle.rs <<'RS'
fn reference(a: &[f32], b: &[f32]) -> f32 {
    let mut s = 0.0f32;
    for i in 0..a.len() {
        s += a[i] * b[i];
    }
    s
}

fn data(n: usize, seed: u32) -> Vec<f32> {
    let mut x = seed;
    (0..n).map(|_| { x = x.wrapping_mul(1_664_525).wrapping_add(1_013_904_223); (x >> 8) as f32 / 65_536.0 - 128.0 }).collect()
}

#[test]
fn bit_identical() {
    for n in [0usize, 1, 3, 7, 8, 15, 16, 17, 64, 1000, 4099] {
        let a = data(n, 1);
        let b = data(n + 5, 2);
        assert_eq!(dot::dot(&a, &b).to_bits(), reference(&a, &b).to_bits(), "n = {n}");
    }
}

#[test]
fn short_b_panics() {
    for n in [1usize, 9, 100] {
        let a = data(n, 3);
        let b = data(n - 1, 4);
        assert!(std::panic::catch_unwind(|| dot::dot(&a, &b)).is_err(), "no panic for n = {n}");
    }
}
RS
cargo test --release -q --test zz_eval_oracle bit_identical

